use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn vec_eq<T>(v1: Vec<T>, v2: Vec<T>) -> bool
    recommends
        v1.len() == v2.len(),
{
    forall|i: int| 0 <= i < v1.len() ==> v1[i] == v2[i]
}

fn solve(t: Vec<char>) -> (result: Vec<char>)
    requires
        t.len() >= 1,  // Non-empty input
    ensures
        result.len() == t.len(),
        vec_eq(result, t),  // All elements are equal
{
    let mut result_vec: Vec<char> = Vec::new();
    let mut i: usize = 0;
    
    while i < t.len()
        invariant
            0 <= i <= t.len(),
            result_vec.len() == i as int,
            forall|j: int| 0 <= j < i ==> result_vec[j] == t[j],
        decreases
            t.len() - i,
    {
        result_vec.push(t[i]);
        i = i + 1;
    }
    
    result_vec
}

}
